import * as React from "react";

export type MobilePhoneIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MobilePhoneIcon({ size = 20, ...props }: MobilePhoneIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="7.5" y="3.5" width="9" height="17" rx="1.5" /><path d="M10.5 6 L13.5 6 M12 17.5 L12.1 17.5" />
    </svg>
  );
}
